        @(posedge clk);
        #1;
        check_out(1'b1, "Reset held: in=0 on clock edge keeps state B");
        in = 1;
        @(posedge clk);
        #1;
        check_out(1'b1, "Reset held: in=1 on clock edge keeps state B");

        // Release reset
        areset = 0;
        #1;
        check_out(1'b1, "After reset release, should remain in state B");

        // 3. Test B --1--> B
        @(negedge clk);
        in = 1;
        @(posedge clk);
        #1;
        check_out(1'b1, "B --1--> B (out should be 1)");

        // 4. Test B --0--> A
        @(negedge clk);
        in = 0;
        @(posedge clk);
        #1;
        check_out(1'b0, "B --0--> A (out should be 0)");

        // 5. Test A --1--> A
        @(negedge clk);
        in = 1;
        @(posedge clk);
        #1;
        check_out(1'b0, "A --1--> A (out should be 0)");

        // 6. Test A --0--> B
        @(negedge clk);
        in = 0;
        @(posedge clk);
        #1;
        check_out(1'b1, "A --0--> B (out should be 1)");

        // 7. Transition to A again: B --0--> A
        @(negedge clk);
        in = 0;
        @(posedge clk);
        #1;
        check_out(1'b0, "B --0--> A (out should be 0)");

        // 8. Test asynchronous reset assertion while in state A (between clocks)
        #2; // mid-cycle
        areset = 1;
        #1;
        check_out(1'b1, "Async reset asserted mid-cycle in state A -> immediate B");

        // Release reset
        #2;
        areset = 0;
        #1;
        check_out(1'b1, "State should remain B after async reset deasserts");

        // 9. Further cycle verification: A --0--> B --0--> A --0--> B
        @(negedge clk);
        in = 0;
        @(posedge clk);
        #1;
        check_out(1'b0, "B --0--> A");

        @(negedge clk);
        in = 0;
        @(posedge clk);
        #1;
        check_out(1'b1, "A --0--> B");

